// n8n Function Node Code
// Remove data:image URLs from markdown content

// Get the markdown content from input using your exact path
const markdownContent = $input.first().json.data.markdown;

// Regular expression to match data:image URLs in parentheses
const dataImageRegex = /\(data:image\/[^)]*\)/g;

// Remove all data:image URLs and replace with empty parentheses
const cleanedMarkdown = markdownContent.replace(dataImageRegex, '()');

// Return the cleaned markdown with same structure
return [{
  json: {
    data: {
      markdown: cleanedMarkdown
    }
  }
}];
